// !: Needs the editing photo option to be added later.

// Connect to the database
require_once "helpers/config.php";

// If there is no session, start it
if (session_status() === PHP_SESSION_NONE) {
    session_start();
}
// Require login
if (!isset($_SESSION['user_id'])) {
    header('Location: login.php');
    exit;
}

$userId  = (int) $_SESSION['user_id'];
$message = "";
$ok      = false;

// Save changes when the form is submitted
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $first = trim($_POST['first_name'] ?? '');
    $last  = trim($_POST['last_name'] ?? '');
    $email = trim($_POST['email'] ?? '');
    $phone = trim($_POST['phone'] ?? '');

    if ($first === '' || $last === '' || $phone === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        $message = "Please fill in every field with a valid email.";
    } else {
        try {
            $stmt = $conn->prepare(
                "UPDATE Users SET First_Name = ?, Last_Name = ?, Email = ?, Phone_Number = ? WHERE User_ID = ?"
            );
            $stmt->bind_param("ssssi", $first, $last, $email, $phone, $userId);
            $stmt->execute();
            $stmt->close();
            $message = "Changes saved.";
            $ok = true;
        } catch (mysqli_sql_exception $e) {
            // Email is UNIQUE in the Users table, so a duplicate lands here
            $message = "Could not save changes. That email may already be in use.";
        }
    }
}

// Load the current values (after any save, so the page shows the latest)
$stmt = $conn->prepare(
    "SELECT First_Name, Last_Name, Email, Phone_Number FROM Users WHERE User_ID = ?"
);
$stmt->bind_param("i", $userId);
$stmt->execute();
$user = $stmt->get_result()->fetch_assoc();
$stmt->close();

if (!$user) {
    die("User not found.");
}

// Placeholder profile picture (path is relative to this file)
$photoSrc = "images/profile_pic.png";

function h($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
?>

<!DOCTYPE html>
<html>
    <head>
        <title> User Info </title>
        <link rel="stylesheet" href="styles/main.css">
        <style>
            .profile-photo { width: 120px; height: 120px; border-radius: 50%;
                             border: 4px solid #000; background: #ddd; object-fit: cover;
                             display: block; margin: 0 auto 24px; }
            .profile-row   { display: flex; gap: 16px; justify-content: center; margin-bottom: 16px; }
            .profile-form input { padding: 8px; }
            input[readonly] { background: #eee; cursor: default; }
            .hidden { display: none; }
        </style>
    </head>
    <body>
        <?php
        $title = "Profile";
        include("helpers/header.php");
        ?>

        <div class="page-container">
            <?php if ($message): ?>
                <p class="<?= $ok ? 'success' : 'fail' ?>"><?= h($message) ?></p>
            <?php endif; ?>

            <div class="card profile-form">
                <img class="profile-photo" src="<?= h($photoSrc) ?>" alt="Profile photo">

                <form method="POST" action="UserInfo.php" id="infoForm">
                    <div class="profile-row">
                        <input type="text" name="first_name" placeholder="First Name"
                               value="<?= h($user['First_Name']) ?>" readonly required>
                        <input type="text" name="last_name" placeholder="Last Name"
                               value="<?= h($user['Last_Name']) ?>" readonly required>
                    </div>
                    <div class="profile-row">
                        <input type="email" name="email" placeholder="Email"
                               value="<?= h($user['Email']) ?>" readonly required>
                    </div>
                    <div class="profile-row">
                        <input type="tel" name="phone" placeholder="Phone"
                               value="<?= h($user['Phone_Number']) ?>" readonly required>
                    </div>

                    <div class="profile-row">
                        <!-- Shown by default -->
                        <button type="button" class="btn" id="editBtn">Make Changes</button>
                        <!-- Hidden until Make Changes is clicked -->
                        <span id="saveCancel" class="hidden">
                            <button type="submit" class="btn btn-green">Save</button>
                            <button type="button" class="btn" id="cancelBtn">Cancel</button>
                        </span>
                    </div>
                </form>

                <div class="profile-row">
                    <a class="btn" href="changePassword.php">Reset Password</a>
                </div>
            </div>
        </div>

        <script>
            const inputs     = document.querySelectorAll('#infoForm input');
            const editBtn    = document.getElementById('editBtn');
            const saveCancel = document.getElementById('saveCancel');

            editBtn.addEventListener('click', () => {
                inputs.forEach(i => i.readOnly = false);
                editBtn.classList.add('hidden');
                saveCancel.classList.remove('hidden');
            });
            // Cancel: reload so the saved values come back
            document.getElementById('cancelBtn').addEventListener('click', () => location.reload());
        </script>
    </body>
</html>